mapper.select:


del_flag = '0'

    and activity_id = #{activityId}


    and object_code = #{objectCode}


    and object_name like concat('%', #{objectName}, '%')


    and object_type = #{objectType}


    and summary like concat('%', #{summary}, '%')


    and subject_code_1 = #{subjectCode1}


    and subject_code_2 = #{subjectCode2}


    and subject_code_3 = #{subjectCode3}


    and category_codes = #{categoryCodes}


    and keywords = #{keywords}


    and org_name like concat('%', #{orgName}, '%')


    and contact_name like concat('%', #{contactName}, '%')


    and contact_phone = #{contactPhone}


    and contact_email = #{contactEmail}


    and submit_status = #{submitStatus}


    and submit_time = #{submitTime}


    and submitted_by = #{submittedBy}


    and locked_time = #{lockedTime}


    and invalid_time = #{invalidTime}


    and created_from = #{createdFrom}


    and source_module = #{sourceModule}


    and source_biz_type = #{sourceBizType}


    and source_biz_id = #{sourceBizId}


    and source_team_id = #{sourceTeamId}


    and source_registration_id = #{sourceRegistrationId}


    and extra_data = #{extraData}


    order by id desc


where activity_id = #{activityId}
  and source_module = #{sourceModule}
  and source_biz_type = #{sourceBizType}
  and source_biz_id = #{sourceBizId}
  and del_flag = '0'
limit 1
